# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Api::V1::Agent::TimesheetEntries through the entry gateway", type: :request do
  let(:company) { create(:company, plan_tier: "free") }
  let(:user) { create(:user, current_workspace_id: company.id) }
  let(:colleague) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:agent) { create(:agent, company:, user:, default_project: project, provider: "codex") }
  let(:colleague_agent) { create(:agent, company:, user: colleague, default_project: project, provider: "codex") }
  let(:agent_token) { AgentKey.issue_for(agent:, name: "Primary Key", created_by: user).last }
  let(:agent_headers) { { "Authorization" => "Bearer #{agent_token}" } }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  around { |example| with_forwarded_timekeeping_env { example.run } }

  before do
    [user, colleague].each do |member|
      create(:employment, company:, user: member)
      member.add_role :employee, company
      create(:project_member, project:, user: member)
    end
    arrange_forwarded_timekeeping(fake, company:, users: { user => "employee", colleague => "employee" }, project:)
    fake.register_agent(id: agent.id, company_id: company.id, user_id: user.id)
    fake.register_agent(id: colleague_agent.id, company_id: company.id, user_id: colleague.id)
  end

  def forwarded_create_request
    fake.requests.find { |request| request[:method] == "POST" }
  end

  def forwarded_token_claims(request)
    Timekeeping::UserToken.verify(request[:headers]["Authorization"].delete_prefix("Bearer "),
                                  public_key: timekeeping_key_pair.public_key)
  end

  # "The forwarded agent token names the authenticated agent and the agent's user as actor"
  # "The forwarded agent token carries `agent_id` equal to the current agent and `sub` equal to the agent's user."
  # "The agent writer's context carries the authenticated agent, so its token is minted with `agent:` set to it, and `UserToken`'s AgentMismatchError check applies."
  # The request names a colleague's agent and user both at the top level and inside the entry, and asks for
  # approval: none of that may move the entry, the token or the review status.
  it "forwards an agent create naming only the authenticated agent, its user and company, whatever the request sends" do
    send_request :post, api_v1_agent_timesheet_entries_path, params: {
      agent_id: colleague_agent.id, user_id: colleague.id,
      timesheet_entry: {
        duration_minutes: 30, work_date: Date.current.iso8601, note: "Smuggled identity",
        agent_id: colleague_agent.id, user_id: colleague.id, review_status: "approved"
      }
    }, headers: agent_headers

    expect(response).to have_http_status(:ok)
    create_request = forwarded_create_request
    expect(create_request).not_to be_nil
    expect(create_request[:path]).to eq("/v1/companies/#{company.id}/entries")
    expect(create_request[:body]).to include("agent_id" => agent.id, "user_id" => user.id)
    expect(create_request[:body]).not_to have_key("review_status")

    claims = forwarded_token_claims(create_request)
    expect(claims.agent_id).to eq(agent.id)
    expect(claims.user_id).to eq(user.id)
    expect(claims.company_id).to eq(company.id)

    stored = fake.stored_entry(json_response.dig("entry", "id"))
    expect(stored).to include("agent_id" => agent.id, "user_id" => user.id, "review_status" => "pending_review")
    snapshot = fake.outbox.last.fetch("entry")
    expect(snapshot).to include("agent_id" => agent.id, "user_id" => user.id, "company_id" => company.id)
    expect(json_response.dig("entry", "agent_id")).to eq(agent.id)
    expect(json_response.dig("entry", "review_status")).to eq("pending_review")
  end

  it "forwards an agent create that stores run_123 and session_123 in Timekeeping and its one snapshot, with no local row" do
    expect do
      send_request :post, api_v1_agent_timesheet_entries_path, params: {
        timesheet_entry: {
          duration_minutes: 60, work_date: Date.current.iso8601, note: "Forwarded agent work",
          source_metadata: { tool: "claude-code", skill: "gstack-review", pii: "drop-me" },
          proof_url: "https://example.test/runs/123",
          external_run_id: "run_123", external_session_id: "session_123"
        }
      }, headers: agent_headers
    end.not_to change(TimesheetEntry, :count)

    expect(response).to have_http_status(:ok)
    entry_id = json_response.dig("entry", "id")

    # "A forwarded agent create with `external_run_id: "run_123"` and `external_session_id: "session_123"` stores both, and both appear in the snapshot."
    stored = fake.stored_entry(entry_id)
    expect(stored).to include("external_run_id" => "run_123", "external_session_id" => "session_123",
                              "agent_id" => agent.id, "user_id" => user.id, "source" => "automation",
                              "review_status" => "pending_review",
                              "source_metadata" => { "tool" => "claude-code", "skill" => "gstack-review" })
    snapshots = fake.outbox.map { |row| row["entry"] }.select { |entry| entry["id"] == entry_id }
    expect(snapshots.size).to eq(1)
    expect(snapshots.first).to include("external_run_id" => "run_123", "external_session_id" => "session_123",
                                       "agent_id" => agent.id)

    # The legacy agent create answers pending_review; the route keeps its JSON.
    expect(json_response.dig("entry", "review_status")).to eq("pending_review")
    expect(json_response.dig("entry", "agent_name")).to eq(agent.name)
  end

  context "during a handoff" do
    before { TimekeepingOwnership.current.update!(handoff_step: "close_admission") }

    it "refuses an agent create with 503 ownership_moving and persists nothing in either store" do
      expect do
        send_request :post, api_v1_agent_timesheet_entries_path, params: {
          timesheet_entry: {
            duration_minutes: 30, work_date: Date.current.iso8601, note: "During handoff",
            external_run_id: "run_123", external_session_id: "session_123"
          }
        }, headers: agent_headers
      end.not_to change(TimesheetEntry, :count)

      # "When `handoff_step` is set, the gateway refuses entry writes, prepares and service commands with a retryable `503 ownership_moving`."
      expect(response).to have_http_status(:service_unavailable)
      expect(json_response["reason"]).to eq("ownership_moving")
      expect(response.headers["Retry-After"]).to be_present
      expect(fake.requests).to be_empty
      expect(fake.outbox).to be_empty
    end
  end

  context "with a project of another company" do
    let(:other_company) { create(:company, plan_tier: "free") }
    let(:foreign_project) { create(:project, billable: true, client: create(:client, company: other_company)) }

    before { fake.register_project(id: foreign_project.id, company_id: other_company.id) }

    it "answers 404 to a forwarded agent create naming that project and forwards nothing" do
      send_request :post, api_v1_agent_timesheet_entries_path, params: {
        timesheet_entry: { project_id: foreign_project.id, duration_minutes: 30, work_date: Date.current.iso8601 }
      }, headers: agent_headers

      expect(response).to have_http_status(:not_found)
      expect(fake.requests.none? { |request| request[:method] == "POST" }).to be(true)
      expect(fake.outbox).to be_empty
    end
  end
end
